function withHumor(id,t){const h=HUMOR[id];if(!h||typeof t.scenario!=='string')return t;const line=pick(h.l);
 if(h.m==='pre')t.scenario=line+' '+t.scenario;else{const i=t.scenario.indexOf('<');t.scenario=i<0?line:line+t.scenario.slice(i)}return t}
const LETTERS='ABCDEFGH';
/* Mehrere richtige Antworten: Buchstaben in beliebiger Reihenfolge. items: [Zeile, richtig?, Begründung]. */
function setTask(text,items,prompt,plain,why,o={}){
 const it=o.keep?items.slice():shuffle(items);
 const listing=it.map((x,i)=>LETTERS[i]+'  '+x[0]).join('\n');
 const ans=it.map((x,i)=>x[1]?LETTERS[i]:'').join('');
 const list=o.plainList?'<div class="calc set-list">'+esc(listing)+'</div>':cs(listing);
 const detail='<ul class="set-why">'+it.map((x,i)=>'<li><b>'+LETTERS[i]+'</b> '+(x[1]?'✓':'✗')+' '+esc(x[0])+': '+x[2]+'</li>').join('')+'</ul>';
 return {kind:'set',scenario:text+list,prompt,plain,answer:ans,n:it.length,why:why+detail,show:'<code>'+ans+'</code>',fmt:'Alle passenden Buchstaben eingeben, Reihenfolge egal, z. B. AC.',key:text+listing+prompt,v:o.checks?{checks:o.checks}:undefined};
}
/* Freitext: groups = Listen gleichwertiger Schlüsselwörter, need = wie viele Gruppen getroffen werden müssen. */
function free(text,prompt,plain,groups,need,sample,why){
 return {kind:'free',scenario:text,prompt,plain,answer:sample,groups,need,why,show:esc(sample),fmt:need>1?'Ein kurzer Satz reicht. Gewertet wird, ob die entscheidenden Begriffe vorkommen.':'Ein Stichwort oder ein kurzer Satz reicht.',key:text+prompt};
}
/* Reihenfolge von Alltagsschritten, kein Code. */
function orderText(text,lines,prompt,plain,why){
 let idx;do{idx=shuffle(lines.map((_,i)=>i))}while(idx.every((v,i)=>v===i));
 const listing=idx.map((n,i)=>LETTERS[i]+'  '+lines[n]).join('\n');
 const ans=lines.map((_,n)=>LETTERS[idx.indexOf(n)]).join('');
 return {kind:'order',scenario:text+'<div class="calc set-list">'+esc(listing)+'</div>',prompt,plain,answer:ans,why,show:'<code>'+ans+'</code>',fmt:'Nur die Buchstaben in der richtigen Reihenfolge, z. B. BADC.',key:text+lines.join('|')};
}
function chkOf(code,c){return c==='bad'?{code,bad:true}:c==='ok'?{code,ok:true}:{code,exc:c.slice(4)}}

