S('daten','v_decl','write',()=>{const [t,n,v,txt]=pick([['int','ports','24','die ganze Zahl 24'],['string','name','"Router"','den Text Router'],['bool','online','true','den Wert wahr'],['decimal','preis','19.99m','den exakten Betrag 19,99'],['char','klasse',"'A'",'das einzelne Zeichen A'],['double','last','0.75','die Kommazahl 0,75']]);return code(`Du brauchst eine Variable namens ${n} für ${txt}.`,'Schreibe die vollständige Zeile mit passendem Datentyp.','Aufbau: Typ, Name, =, Wert, Semikolon.',[`${t} ${n}=${v};`,`var ${n}=${v};`],`Aufbau: Typ, Name, Gleichheitszeichen, Wert, Semikolon. Also: ${t} ${n} = ${v};`,'@@')});
const VF=[['int alter = "40";','int alter = 40;','Eine Zahl steht ohne Anführungszeichen.'],['string name = Router;','string name = "Router";','Text braucht Anführungszeichen.'],['bool aktiv = "true";','bool aktiv = true;','true ist ein Wahrheitswert, kein Text.'],['decimal preis = 19.99;','decimal preis = 19.99m;','Ohne m ist 19.99 ein double. decimal braucht das Suffix.'],["char c = 'AB';","char c = 'A';",'Ein char enthält genau ein Zeichen.'],['int zahl = 3.5;','double zahl = 3.5;','3.5 passt nicht in einen int. Es braucht einen Typ für Kommazahlen.']];
S('typen','v_fix','fix',()=>{const [b,a,y]=pick(VF);const i=VF.findIndex(x=>x[0]===b);return code('Der Compiler lehnt diese Zeile ab.','Schreibe die korrigierte Zeile. Der Variablenname bleibt gleich.','Passen Typ und Wert zusammen?',i===5?[a,'decimal zahl = 3.5m;','int zahl = 3;']:[a],y,'@@',{show:b})});
S('umwandeln','v_parse','write',()=>{const n=pick(['ports','anzahl','menge']);return code(`Die Eingabe liegt als Text in der Variablen eingabe. Du willst damit rechnen und legst ${ic(n)} als int an.`,'Schreibe die Zeile, die den Text umwandelt.','Welche fertige Methode macht aus Text eine ganze Zahl?',[`int ${n}=int.Parse(eingabe);`,`var ${n}=int.Parse(eingabe);`,`int ${n}=Convert.ToInt32(eingabe);`],'int.Parse wandelt Text in eine ganze Zahl um. Ist der Text keine Zahl, gibt es eine FormatException.','string eingabe = "5";\n@@')});
S('daten','v_wert','out',()=>{const a=rint(2,9),b=rint(10,19),c=rint(1,5);return out('Eine Variable bekommt mehrmals einen neuen Inhalt.',`int wert = ${a};\nwert = ${b};\nwert = wert + ${c};\nConsole.WriteLine(wert);`,pre,'Was liegt am Ende in der Schublade?',b+c,`Der Startwert ${a} wird von ${b} ersetzt. Danach gilt ${b} + ${c} = ${b+c}.`)});
S('umwandeln','v_concat','out',()=>{const a=rint(1,9),b=rint(1,9);return pick([()=>out('Hier treffen Text und Zahlen aufeinander.',`Console.WriteLine("${a}" + "${b}");`,pre,'Sind das Zahlen oder Texte?',`${a}${b}`,'Zwei Texte werden mit + aneinandergehängt, nicht addiert.'),()=>out('Hier stehen keine Anführungszeichen.',`Console.WriteLine(${a} + ${b});`,pre,'Sind das Zahlen oder Texte?',a+b,'Zwei int-Werte werden addiert.'),()=>out('Text und Rechnung in einer Zeile. Das Programm liest von links nach rechts.',`Console.WriteLine("Summe: " + ${a} + ${b});`,pre,'Was passiert, sobald links schon Text steht?',`Summe: ${a}${b}`,`Links steht Text. Darum wird ${a} angehängt, danach ${b}. Gerechnet wird nicht. Mit Klammern um ${a} + ${b} wäre es anders.`)])()});
S('umwandeln','v_cast','out',()=>{const w=rint(1,9),f=pick([1,5,9]);return out('Eine Kommazahl wird in einen int umgewandelt.',`double wert = ${w}.${f};\nint ganz = (int)wert;\nConsole.WriteLine(ganz);`,pre,'Was passiert mit den Nachkommastellen?',w,`Die Umwandlung mit (int) schneidet die Nachkommastellen ab. Sie rundet nicht. ${w}.${f} wird zu ${w}.`)});
const VK=[['const int Max = 10;\nMax = 20;','Was passiert beim Kompilieren?','Darf man so einen Wert später ändern?','Fehler: Eine Konstante kann nicht geändert werden.',['Max enthält danach 20.','Max enthält danach 30.','Erst beim Ausführen stürzt das Programm ab.'],'const legt den Wert fest. Der Compiler verweigert jede spätere Zuweisung.'],['var zahl = 5;\nzahl = "fünf";','Was passiert beim Kompilieren?','Macht var eine Variable zum Allesfresser?','Fehler: zahl ist ein int, und das bleibt so.',['zahl wird automatisch zu string.','zahl enthält danach 5 und "fünf".','var erlaubt jeden Typ zu jeder Zeit.'],'var leitet den Typ einmalig aus dem Startwert ab. Hier ist das int.'],['var name;\nname = "Router";','Warum kompiliert das nicht?','Was fehlt dem Compiler, um den Typ zu erkennen?','var braucht in derselben Zeile einen Startwert.',['var ist für Text verboten.','name ist ein reserviertes Wort.','Es fehlt ein zweites Gleichheitszeichen.'],'Ohne Startwert kann der Compiler den Typ nicht ableiten.']];
S('daten','v_konst','mc',()=>{const [c,q,p,r,w,y]=pick(VK);return choice('Ein Kollege experimentiert.',c,q,p,r,w,y)});

S('rechnen','o_int','out',()=>{const a=rint(7,50),b=pick([2,3,4,6,7]);return out('Beide Werte sind int.',`int ergebnis = ${a} / ${b};\nConsole.WriteLine(ergebnis);`,pre,'Was passiert mit dem Rest, wenn zwei ganze Zahlen geteilt werden?',Math.trunc(a/b),`Zwei int-Werte ergeben eine Integerdivision. ${a} / ${b} = ${Math.trunc(a/b)}, ein Rest wird abgeschnitten.`)});
S('rechnen','o_mod','out',()=>{const a=rint(7,60),b=pick([2,3,4,5,8]);return out(`${a} Geräte sollen in Kartons zu je ${b} Stück. Der Code ermittelt, was übrig bleibt.`,`Console.WriteLine(${a} % ${b});`,pre,'Wie groß ist der Rest?',a%b,`${Math.trunc(a/b)} × ${b} = ${Math.trunc(a/b)*b}. Bis ${a} bleiben ${a%b}.`)});
S('rechnen','o_double','out',()=>{const a=pick([1,3,5,7,9,11]),b=pick([2,4]);const r=a/b,s=String(r);return out('Diesmal ist einer der Werte ein double.',`Console.WriteLine(${a} / ${b}.0);`,pre,'Wird hier mit oder ohne Nachkommastellen gerechnet?',s,`${b}.0 ist ein double, also wird echt geteilt. Auf einem deutschen System zeigt die Konsole ein Komma.`,{accept:[s,s.replace('.',',')],fmt:'Komma oder Punkt sind beide richtig.'})});
S('rechnen','o_rang','out',()=>{const a=rint(1,9),b=rint(2,6),c=rint(2,6);return pick([()=>out('Rechnen nach alter Schule.',`Console.WriteLine(${a} + ${b} * ${c});`,pre,'Was wird zuerst gerechnet?',a+b*c,`Punkt vor Strich: erst ${b} × ${c} = ${b*c}, dann plus ${a}.`),()=>out('Klammern ändern die Reihenfolge.',`Console.WriteLine((${a} + ${b}) * ${c});`,pre,'Was wird zuerst gerechnet?',(a+b)*c,`Die Klammer zuerst: ${a+b}. Dann mal ${c}.`)])()});
S('rechnen','o_inkr','out',()=>{const a=rint(2,20);return pick([()=>out('Das ++ steht hinter der Variablen.',`int x = ${a};\nConsole.WriteLine(x++);\nConsole.WriteLine(x);`,pre,'Wird erst ausgegeben oder erst erhöht?',`${a} ${a+1}`,'x++ liefert den alten Wert und erhöht danach.'),()=>out('Das ++ steht vor der Variablen.',`int x = ${a};\nConsole.WriteLine(++x);\nConsole.WriteLine(x);`,pre,'Wird erst ausgegeben oder erst erhöht?',`${a+1} ${a+1}`,'++x erhöht zuerst und liefert dann den neuen Wert.'),()=>out('Eine Variable zählt herunter.',`int x = ${a};\nx--;\nConsole.WriteLine(x);`,pre,'Was macht -- mit dem Wert?',a-1,'x-- verringert um 1.')])()});
S('rechnen','o_logik','out',()=>{const a=pick([true,false]),b=pick([true,false]),s=x=>x?'true':'false',up=x=>x?'True':'False',[e,r,y]=pick([[`a && b`,a&&b,'&& ist nur wahr, wenn beide Seiten wahr sind.'],[`a || b`,a||b,'|| ist wahr, wenn mindestens eine Seite wahr ist.'],[`!a`,!a,'! dreht den Wert um.'],[`!a || b`,!a||b,'Zuerst wird ! ausgewertet, danach ||.']]);return out('Ein Port ist offen (a), ein Dienst läuft (b).',`bool a = ${s(a)};\nbool b = ${s(b)};\nConsole.WriteLine(${e});`,pre,'Setze die Werte in den Ausdruck ein.',up(r),y,{fmt:'Exakt so, wie die Konsole es schreibt.'})});

S('wenn','i_zweig','out',()=>{const v=rint(10,25),g=18;return out('Der Türsteher des Serverraums.',`int alter = ${v};\nif (alter >= ${g})\n{\n    Console.WriteLine("Rein");\n}\nelse\n{\n    Console.WriteLine("Raus");\n}`,pre,'Stimmt die Bedingung oder nicht?',v>=g?'Rein':'Raus',`${v} >= ${g} ist ${v>=g?'wahr':'falsch'}, also läuft der ${v>=g?'erste Block':'else-Block'}.`)});
S('wenn','i_elseif','out',()=>{const v=rint(0,100);return out('Festplatten-Ampel, freier Speicher in Prozent.',`int frei = ${v};\nif (frei < 10)\n{\n    Console.WriteLine("Rot");\n}\nelse if (frei < 30)\n{\n    Console.WriteLine("Gelb");\n}\nelse\n{\n    Console.WriteLine("Grün");\n}`,pre,'Welche Prüfung trifft zuerst zu?',v<10?'Rot':v<30?'Gelb':'Grün',`Von oben geprüft: ${v} ${v<10?'ist kleiner als 10':v<30?'ist nicht kleiner als 10, aber kleiner als 30':'ist weder kleiner als 10 noch als 30'}.`)});
S('wenn','i_switch','out',()=>{const c=pick(['1','2','3','9']),m={'1':'Neu','2':'Liste','3':'Suche'};return out('Ein Menü wertet die Auswahl aus.',`string wahl = "${c}";\nswitch (wahl)\n{\n    case "1":\n        Console.WriteLine("Neu");\n        break;\n    case "2":\n        Console.WriteLine("Liste");\n        break;\n    case "3":\n        Console.WriteLine("Suche");\n        break;\n    default:\n        Console.WriteLine("Hä?");\n        break;\n}`,pre,'Welcher Fall passt zur Auswahl?',m[c]||'Hä?',m[c]?`Der Fall "${c}" passt.`:'Kein Fall passt, also läuft default.')});
S('wenn','i_op','gap',()=>{const [t,a,tpl,sh,y]=pick([['Der Text soll nur bei genau 443 erscheinen.','==','if (port @@ 443) { }','if (port ____ 443)','== vergleicht auf Gleichheit.'],['Die Warnung soll erscheinen, wenn der Wert nicht 0 ist.','!=','if (port @@ 0) { }','if (port ____ 0)','!= prüft auf Ungleichheit.'],['Die Warnung soll bei 100 und mehr erscheinen.','>=','if (port @@ 100) { }','if (port ____ 100)','>= schließt die 100 mit ein.'],['Der Zweig soll laufen, wenn der Wert kleiner als 1024 ist.','<','if (port @@ 1024) { }','if (port ____ 1024)','< schließt 1024 selbst aus.']]);return code(t,'Welcher Operator gehört in die Lücke?','Wie drückst du diesen Vergleich aus?',a,y,'int port = 1;\n'+tpl,{show:sh,fmt:'Nur den Operator eingeben.'})});
S('wenn','i_gleich','fix',()=>{const n=rint(1,9);return code('Der Compiler meldet: „Der Typ int kann nicht implizit in bool konvertiert werden.“','Schreibe die korrigierte erste Zeile.','Soll hier zugewiesen oder verglichen werden?',`if (x == ${n})`,'Ein einzelnes = weist zu, == vergleicht. if braucht einen bool, und x = '+n+' liefert einen int.',`int x = 1;\n@@\n{\n}`,{show:`if (x = ${n})\n{\n    Console.WriteLine("Treffer");\n}`})});
S('wenn','i_nest','out',()=>{const on=pick([true,false]),l=rint(50,99);return out('Ein Server wird nur geprüft, wenn er läuft.',`bool online = ${on};\nint last = ${l};\nif (online)\n{\n    if (last > 80)\n    {\n        Console.WriteLine("Überlast");\n    }\n    else\n    {\n        Console.WriteLine("Normal");\n    }\n}\nelse\n{\n    Console.WriteLine("Aus");\n}`,pre,'Prüfe erst die äußere, dann die innere Bedingung.',!on?'Aus':l>80?'Überlast':'Normal',!on?'online ist false, die innere Prüfung wird gar nicht erreicht.':`online ist true. Danach: ${l} > 80 ist ${l>80?'wahr':'falsch'}.`)});
S('wenn','i_logik','out',()=>{const p=pick([22,80,443,8080]),on=pick([true,false]);return out('Eine Firewall-Regel lässt nur 80 oder 443 durch, und auch nur, wenn sie aktiv ist.',`int port = ${p};\nbool aktiv = ${on};\nif (aktiv && (port == 80 || port == 443))\n{\n    Console.WriteLine("Frei");\n}\nelse\n{\n    Console.WriteLine("Gesperrt");\n}`,pre,'Beide Teile der Bedingung müssen stimmen.',on&&(p===80||p===443)?'Frei':'Gesperrt',`aktiv ist ${on?'wahr':'falsch'}, und der Port ${p===80||p===443?'passt':'passt nicht'}. && verlangt beides.`)});
S('wenn','i_text','set',()=>{const vals=shuffle(['Ja','ja','JA','jA','Nein']).slice(0,4);if(!vals.includes('Ja'))vals[0]='Ja';const it=shuffle(vals).map(v=>[`antwort = "${v}"`,v==='Ja',v==='Ja'?'exakt gleich, also Löschen.':'unterscheidet sich in Groß- und Kleinschreibung oder ist ein anderes Wort, also Abbruch.']);const code0=`if (antwort == "Ja")\n{\n    Console.WriteLine("Löschen");\n}\nelse\n{\n    Console.WriteLine("Abbruch");\n}`;return setTask('Eine Sicherheitsabfrage vor dem Löschen.'+cs('string antwort = EINGABE;\n'+code0)+'Mögliche Eingaben:',it,'Bei welchen Eingaben wird gelöscht?','Ist == bei Text streng oder großzügig?','== vergleicht Text exakt, auch die Groß- und Kleinschreibung. Wer großzügig vergleichen will, braucht etwa antwort.ToLower() == "ja".',{plainList:true,checks:it.map(([a,ok])=>({code:'string '+a+';\n'+code0,out:ok?'Löschen':'Abbruch'}))})});

S('schleife','l_anzahl','out',()=>{const a=pick([0,1,2]),n=rint(4,12),st=pick([1,2]),cmp=pick(['<','<=']);let c=0;for(let i=a;cmp==='<'?i<n:i<=n;i+=st)c++;const seq=[];for(let i=a;(cmp==='<'?i<n:i<=n);i+=st)seq.push(i);return out('Die Schleife schreibt pro Durchlauf einen Punkt. Der Zähler am Ende verrät die Anzahl.',`int zaehler = 0;\nfor (int i = ${a}; i ${cmp} ${n}; i += ${st})\n{\n    zaehler++;\n}\nConsole.WriteLine(zaehler);`,'Wie oft läuft die Schleife? Gib den Wert von zaehler an.','Schreib alle Werte von i auf und zähle sie.',c,`i nimmt die Werte ${seq.join(', ')} an. Das sind ${c} Durchläufe.`)});
S('schleife','l_summe','out',()=>{const n=rint(3,7);let s=0;for(let i=1;i<=n;i++)s+=i;return out('Eine Schleife addiert die Portnummern 1 bis '+n+'.',`int summe = 0;\nfor (int i = 1; i <= ${n}; i++)\n{\n    summe += i;\n}\nConsole.WriteLine(summe);`,pre,'Addiere alle Werte von i.',s,Array.from({length:n},(_,i)=>i+1).join(' + ')+' = '+s+'.')});
S('schleife','l_while','out',()=>{const a=rint(1,3),st=rint(2,3),e=rint(8,12);const seq=[];let x=a;while(x<e){seq.push(x);x+=st}return out('Die Bedingung wird vor jedem Durchlauf geprüft.',`int x = ${a};\nwhile (x < ${e})\n{\n    Console.WriteLine(x);\n    x += ${st};\n}`,pre,'Schreibe die Werte auf, solange die Bedingung stimmt.',seq.join(' '),`x wird ${seq.join(', ')} und dann ${x}. ${x} < ${e} ist falsch, Schluss.`)});
S('schleife','l_do','mc',()=>{const a=rint(5,9),g=rint(1,4);const v=pick(['do','while']);const body=v==='do'?`int n = ${a};\nint laeufe = 0;\ndo\n{\n    laeufe++;\n    n++;\n} while (n < ${g});\nConsole.WriteLine(laeufe);`:`int n = ${a};\nint laeufe = 0;\nwhile (n < ${g})\n{\n    laeufe++;\n    n++;\n}\nConsole.WriteLine(laeufe);`;const r=v==='do'?'Genau einmal':'Kein einziges Mal';return choice(v==='do'?'Die Bedingung ist von Anfang an falsch. Aber es ist eine do-while-Schleife.':'Die Bedingung ist von Anfang an falsch, diesmal mit while.',body,'Wie oft läuft der Block der Schleife?',v==='do'?'Wann wird bei do while geprüft: vor oder nach dem Block?':'Wann wird bei while geprüft: vor oder nach dem Block?',r,['Kein einziges Mal','Genau einmal','Endlos, bis jemand den Stecker zieht',`${g}-mal`].filter(x=>x!==r),v==='do'?'do while prüft erst nach dem Block. Der Block läuft also mindestens einmal, auch wenn die Bedingung von Anfang an falsch ist.':'while prüft vor dem Block. Ist die Bedingung von Anfang an falsch, läuft der Block kein einziges Mal.',{v:{checks:[{code:body,out:v==='do'?'1':'0'}]}})});
S('schleife','l_foreach','out',()=>{const a=shuffle(GER).slice(0,3);return out('Alle Geräte werden gemeldet.',`string[] geraete = { ${a.map(x=>`"${x}"`).join(', ')} };\nforeach (string g in geraete)\n{\n    Console.Write(g[0]);\n}`,'Was steht im Terminal?','g[0] ist der erste Buchstabe des aktuellen Geräts.',a.map(x=>x[0]).join(''),'foreach nimmt jedes Element der Reihe nach. g[0] liefert davon das erste Zeichen. Write bricht nicht um.',{fmt:'Genau das eingeben, was die Konsole zeigt.'})});
S('schleife','l_break','out',()=>{const n=rint(6,9),k=rint(2,5);return pick([()=>{const s=[];for(let i=1;i<=n;i++){if(i===k)break;s.push(i)}return out('Beim ersten kaputten Gerät wird abgebrochen.',`for (int i = 1; i <= ${n}; i++)\n{\n    if (i == ${k})\n    {\n        break;\n    }\n    Console.WriteLine(i);\n}`,pre,'Was macht break mit der gesamten Schleife?',s.join(' '),`Bei i = ${k} verlässt break die Schleife, bevor ${k} ausgegeben wird.`)},()=>{const s=[];for(let i=1;i<=n;i++){if(i===k)continue;s.push(i)}return out('Ein Gerät wird übersprungen.',`for (int i = 1; i <= ${n}; i++)\n{\n    if (i == ${k})\n    {\n        continue;\n    }\n    Console.WriteLine(i);\n}`,pre,'Was macht continue mit dem aktuellen Durchlauf?',s.join(' '),`continue springt bei i = ${k} sofort zum nächsten Durchlauf. Nur die ${k} fehlt.`)}])()});
const LE=[['int i = 0;\nwhile (i < 5)\n{\n    Console.WriteLine(i);\n}','Das Hochzählen fehlt. i bleibt immer 0.'],['for (int i = 0; i < 5; i--)\n{\n    Console.WriteLine(i);\n}','i wird kleiner statt größer und bleibt also unter 5. Sinnvoll wäre i++.'],['int i = 1;\nwhile (i != 10)\n{\n    i += 2;\n}','i wird 1, 3, 5, 7, 9, 11 und trifft die 10 nie. Die Prüfung müsste i < 10 heißen.']];
S('schleife','l_endlos','mc',()=>{const [c,y]=pick(LE);return choice('Der Lüfter dreht hoch, das Programm hängt.',c,'Was ist die Ursache?','Warum wird die Bedingung nie falsch?',y,LE.filter(x=>x[1]!==y).map(x=>x[1]).concat(['Es liegt am Monitor. Der war schon immer komisch.']),y)});
S('schleife','l_off','fix',()=>{const n=rint(4,9);return code(`Die Schleife soll genau ${n}-mal laufen, läuft aber einmal zu oft.`,'Schreibe den korrigierten Schleifenkopf.','Start 0: Welcher Vergleich ergibt genau '+n+' Durchläufe?',[`for (int i = 0; i < ${n}; i++)`,`for (int i = 0; i <= ${n-1}; i++)`,`for (int i = 1; i <= ${n}; i++)`],`Von 0 bis ${n-1} sind es genau ${n} Durchläufe, also i < ${n}.`,'@@\n{\n}',{show:`for (int i = 0; i <= ${n}; i++)`})});
S('schleife','l_kopf','write',()=>{const n=rint(5,20);return code(`Die Zahlen von 1 bis ${n} sollen ausgegeben werden.`,'Schreibe den passenden Schleifenkopf.','Start, Bedingung, Schritt. Die Variable heißt i.',[`for (int i = 1; i <= ${n}; i++)`,`for (int i = 1; i < ${n+1}; i++)`,`for (int i = 1; i <= ${n}; i += 1)`,`for (int i = 1; i <= ${n}; ++i)`,`for (var i = 1; i <= ${n}; i++)`],`Start bei 1, weiter bis einschließlich ${n}, Schritt 1.`,'@@\n{\n    Console.WriteLine(i);\n}',{show:`____\n{\n    Console.WriteLine(i);\n}`})});

S('liste','a_index','out',()=>{const a=shuffle(GER).slice(0,4),i=rint(0,3);return out('Ein Array mit Geräten.',`string[] namen = { ${a.map(x=>`"${x}"`).join(', ')} };\nConsole.WriteLine(namen[${i}]);`,pre,'Zähle ab 0.',a[i],`Die Zählung beginnt bei 0. Index ${i} ist also das ${i+1}. Element.`)});
S('liste','a_letzt','out',()=>{const a=shuffle(GER).slice(0,rint(3,5));return out('Das letzte Element wird berechnet, statt die Position fest einzutragen.',`string[] namen = { ${a.map(x=>`"${x}"`).join(', ')} };\nConsole.WriteLine(namen[namen.Length - 1]);`,pre,'Length zählt ab 1, der Index ab 0.',a[a.length-1],`Length ist ${a.length}, der letzte Index also ${a.length-1}.`)});
S('liste','a_grenze','mc',()=>{const n=rint(2,4);return choice('Das Programm kompiliert, stürzt aber beim Ausführen ab.',`int[] werte = new int[${n}];\nConsole.WriteLine(werte[${n}]);`,'Warum stürzt es ab?','Welche Indizes hat ein Array dieser Größe?',`Gültig sind nur die Indizes 0 bis ${n-1}.`,['In neuen Arrays darf man nicht lesen.',`Das Array hat ${n+1} Elemente, aber nur eines ist belegt.`,'WriteLine kann keine Zahlen ausgeben.'],`Ein Array mit ${n} Elementen hat die Indizes 0 bis ${n-1}. Der Zugriff auf ${n} löst eine IndexOutOfRangeException aus.`)});
S('liste','a_schreib','write',()=>{const [t,a,y]=pick([['Lies das erste Element des Arrays namen in die Variable erster.',['string erster=namen[0];','var erster=namen[0];'],'Das erste Element hat den Index 0.'],['Lies die Anzahl der Elemente von namen in die Variable anzahl.',['int anzahl=namen.Length;','var anzahl=namen.Length;'],'Arrays nennen ihre Anzahl Length, ohne Klammern.'],['Schreibe den Text "NAS" an die zweite Stelle des Arrays namen.',['namen[1]="NAS";'],'Die zweite Stelle hat den Index 1.'],['Lege ein Array namens ports mit Platz für 4 ganze Zahlen an.',['int[] ports=new int[4];','var ports=new int[4];'],'new int[4] erzeugt vier Plätze mit dem Wert 0.']]);return code(t,'Schreibe die Zeile.','Denk an Index oder Eigenschaft und an das Semikolon.',a,y,'string[] namen = { "a", "b" };\n@@')});
S('liste','a_liste','out',()=>{const a=shuffle(GER).slice(0,4),rm=a[1];return pick([()=>out('Geräte kommen und gehen.',`List<string> liste = new List<string>();\nliste.Add("${a[0]}");\nliste.Add("${a[1]}");\nliste.Add("${a[2]}");\nliste.Remove("${rm}");\nConsole.WriteLine(liste.Count);`,pre,'Wie viele bleiben übrig?',2,'Drei hinzugefügt, eines entfernt. Count zählt, was noch da ist.'),()=>out('Nach dem Entfernen rücken die anderen nach.',`List<string> liste = new List<string> { "${a[0]}", "${a[1]}", "${a[2]}" };\nliste.Remove("${rm}");\nConsole.WriteLine(liste[1]);`,pre,'Wer rutscht auf Index 1?',a[2],`Nach dem Entfernen von ${rm} rückt ${a[2]} auf Index 1 auf.`)])()});
S('liste','a_laenge','write',()=>pick([()=>code('Du brauchst die Anzahl der Elemente der Liste geraete.','Schreibe die Zeile, die sie in anzahl speichert.','Listen benennen die Anzahl anders als Arrays.',['int anzahl=geraete.Count;','var anzahl=geraete.Count;'],'Listen haben Count, Arrays haben Length. Beides ohne Klammern.','List<string> geraete = new List<string>();\n@@'),()=>code('Du brauchst die Anzahl der Zeichen im Text name.','Schreibe die Zeile, die sie in anzahl speichert.','Wie heißt die Eigenschaft bei Text?',['int anzahl=name.Length;','var anzahl=name.Length;'],'Auch ein string nennt seine Anzahl Length.','string name = "NAS";\n@@'),()=>choice('Ein Kollege fragt nach dem Unterschied.','','Wann ist eine Liste statt eines Arrays die bessere Wahl?','Wann brauchst du die flexible Variante?','Wenn die Anzahl der Elemente sich ändern kann.',['Wenn alle Elemente denselben Typ haben.','Wenn der erste Index 1 sein soll.','Wenn du gar keine Elemente speichern willst.'],'Ein Array behält seine Größe. Eine Liste wächst mit Add und schrumpft mit Remove.')])());
S('umwandeln','a_interp','out',()=>{const n=pick(NAME),p=pick([8,16,24,48]);return pick([()=>out('Werte werden direkt in den Text gesetzt.',`string name = "${n}";\nint ports = ${p};\nConsole.WriteLine($"{name} hat {ports} Ports");`,pre,'Was ersetzt die geschweiften Klammern?',`${n} hat ${p} Ports`,'Das $ erlaubt Platzhalter. Jeder Ausdruck in { } wird eingesetzt.'),()=>out('In den Klammern darf sogar gerechnet werden.',`int ports = ${p};\nConsole.WriteLine($"Frei: {ports - 2}");`,pre,'Rechne den Platzhalter aus.',`Frei: ${p-2}`,'In { } steht ein beliebiger Ausdruck.'),()=>out('Hier hat jemand das Dollarzeichen vergessen. Ein Klassiker.',`string name = "${n}";\nConsole.WriteLine("{name} bereit");`,pre,'Ohne $ ist das nur normaler Text.','{name} bereit','Ohne $ sind die Klammern gewöhnliche Zeichen.')])()});

S('liste','m_aufruf','out',()=>{const a=rint(2,9),b=rint(2,9);return out('Eine kleine Methode.',`static int Summe(int a, int b)\n{\n    return a + b;\n}\n\nConsole.WriteLine(Summe(${a}, ${b}));`,pre,'Was gibt die Methode zurück?',a+b,`Summe erhält ${a} und ${b} und gibt ${a+b} zurück.`)});
S('liste','m_param','out',()=>{const a=rint(2,9),b=rint(10,19);return out('Die Reihenfolge der Argumente entscheidet.',`static int Abzug(int gross, int klein)\n{\n    return gross - klein;\n}\n\nConsole.WriteLine(Abzug(${a}, ${b}));`,pre,'Welcher Wert landet in welchem Parameter?',a-b,`Das erste Argument landet im ersten Parameter: gross = ${a}, klein = ${b}. Der Name allein sortiert nichts.`)});
S('liste','m_return','fix',()=>{const [h,a,y]=pick([['static int Doppelt(int x)\n{\n    x * 2;\n}',['return x * 2;'],'Der Wert muss mit return zurückgegeben werden.'],['static bool IstLeer(string s)\n{\n    s.Length == 0;\n}',['return s.Length == 0;'],'Der Vergleich liefert einen bool. return gibt ihn zurück.'],['static string Gruss(string n)\n{\n    "Hallo " + n;\n}',['return "Hallo " + n;'],'Der zusammengesetzte Text muss mit return zurückgegeben werden.']]);const sig=h.split('\n')[0];return code('Der Compiler beschwert sich über die mittlere Zeile.','Schreibe die korrigierte Zeile im Methodenrumpf.','Wie kommt der Wert aus der Methode heraus?',a,y,`${sig}\n{\n    @@\n}`,{show:h})});
S('liste','m_kopf','write',()=>{const [t,a,tpl,y]=pick([['Eine Methode IstAktiv bekommt einen int namens port und liefert wahr oder falsch.',['static bool IstAktiv(int port)'],'return port > 0;','Rückgabetyp bool, ein Parameter vom Typ int.'],['Eine Methode Melde bekommt einen string namens text und liefert nichts zurück.',['static void Melde(string text)'],'','Nichts zurückgeben heißt void.'],['Eine Methode Groesser bekommt zwei int namens a und b und liefert einen int.',['static int Groesser(int a, int b)'],'return a;','Rückgabetyp int, zwei Parameter, getrennt durch ein Komma.']]);return code(t,'Schreibe den Methodenkopf, also die Zeile vor der öffnenden Klammer.','static, Rückgabetyp, Name, Parameter.',a,y,`@@\n{\n    ${tpl}\n}`)});

/* ===== Stufe 1: Was ist ein Programm? ===== */
const W_BEGRIFF=[
 ['Eine Kollegin beschreibt Schritt für Schritt, wie man einen neuen Drucker einrichtet: Treiber laden, installieren, anschließen, Testseite drucken.','Wie nennt man eine solche genaue Schrittfolge zur Lösung einer Aufgabe?','Wie heißt ein sehr genaues Rezept in der Informatik?','Algorithmus',['Compiler','Datentyp','Kommentar'],'Ein Algorithmus ist eine eindeutige, endliche Folge von Schritten, die eine Aufgabe löst. Er kann auf Papier stehen, bevor es irgendeinen Code gibt.'],
 ['Du tippst in VS Code die Datei Program.cs voller C#-Anweisungen.','Wie heißt der Text, den du gerade schreibst?','Wie nennt man den für Menschen lesbaren Programmtext?','Quelltext',['Maschinencode','Laufzeitumgebung','Betriebssystem'],'Quelltext (auch Quellcode) ist der lesbare Text in einer Programmiersprache. Erst nach dem Übersetzen kann die CPU damit etwas anfangen.'],
 ['Die CPU kann nur sehr einfache Befehle als Bitmuster ausführen, etwa „addiere“ oder „springe“.','Wie heißt diese Sprache?','Welche Sprache versteht der Prozessor direkt?','Maschinensprache',['Hochsprache','Auszeichnungssprache','Umgangssprache'],'Maschinensprache besteht aus Bitmustern für einfache CPU-Befehle. Hochsprachen wie C# müssen dorthin übersetzt werden.'],
 ['In deinem Code steht WriteLine("Hallo") ohne Semikolon. Die Regel, dass dort eins hingehört, ist verletzt.','Welcher Teil der Sprache ist verletzt?','Geht es um die Schreibregeln oder um die Bedeutung?','Die Syntax',['Die Semantik','Der Algorithmus','Die Hardware'],'Die Syntax sind die Schreibregeln einer Sprache. Fehlt ein Semikolon, ist die Syntax verletzt. Die Semantik ist die Bedeutung einer Anweisung.'],
 ['Ein Programm ist fehlerfrei geschrieben und läuft. Es zieht aber Mehrwertsteuer ab, statt sie aufzuschlagen.','Wo liegt das Problem?','Ist die Schreibweise falsch oder das, was der Code tut?','In der Semantik, also in der Bedeutung',['In der Syntax, also der Schreibweise','Beim Compiler, der hat geschlafen','Im Monitor, der zeigt Zahlen falsch an'],'Syntaktisch ist alles korrekt, sonst würde das Programm nicht laufen. Die Bedeutung ist falsch. Solche logischen Fehler findet kein Compiler.'],
 ['Ein Fehler im Programm sorgt dafür, dass der Drucker 400 leere Seiten druckt.','Wie nennt man einen Fehler in einem Programm umgangssprachlich?','Welches Tier krabbelt durch kaputten Code?','Bug',['Patch','Feature','Update'],'Ein Bug ist ein Programmfehler. Ein Patch ist die Korrektur. Und „Feature“ ist das, was man einen Bug nennt, wenn der Kunde zuhört.'],
];
S('welt','w_begriff','mc',()=>{const [t,q,p,r,w,y]=pick(W_BEGRIFF);return choice(t,'',q,p,r,w,y)});
const EVA_FAELLE=[
 ['Ein Login-Programm',[['Benutzername und Passwort werden eingetippt.','E'],['Das Programm prüft, ob das Passwort zum Konto passt.','V'],['Das Programm zählt die Fehlversuche mit.','V'],['Die Meldung „Anmeldung erfolgreich“ erscheint.','A'],['Ein Eintrag wird in die Logdatei geschrieben.','A']]],
 ['Ein Speicher-Monitor',[['Das Programm liest den freien Speicher des Laufwerks aus.','E'],['Es rechnet den Wert in Prozent um.','V'],['Es vergleicht den Wert mit der Warngrenze 10 %.','V'],['Eine Warnmail geht an die IT.','A'],['Eine rote Ampel erscheint auf dem Dashboard.','A']]],
 ['Ein Kassensystem in der Kantine',[['Der Scanner liest den Barcode des Joghurts.','E'],['Die Mitarbeiterkarte wird aufgelegt.','E'],['Das System addiert die Preise und zieht den Zuschuss ab.','V'],['Der Bon wird gedruckt.','A'],['Der Betrag erscheint auf dem Display.','A']]],
 ['Ein Ticketsystem',[['Ein Benutzer füllt das Formular „Drucker druckt nicht“ aus.','E'],['Das System ordnet das Ticket der Kategorie Hardware zu.','V'],['Es berechnet aus Kategorie und Dringlichkeit die Priorität.','V'],['Der Benutzer bekommt eine Bestätigungsmail.','A'],['Das Ticket erscheint in der Liste des Supports.','A']]],
];
S('welt','w_eva','set',()=>{const [n,items]=pick(EVA_FAELLE);const [k,name]=pick([['E','Eingabe'],['V','Verarbeitung'],['A','Ausgabe']]);const nm={E:'Eingabe',V:'Verarbeitung',A:'Ausgabe'};return setTask(`${n} arbeitet diese Schritte ab.`,items.map(([s,x])=>[s,x===k,`gehört zur ${nm[x]}.`]),`Welche Schritte gehören zur ${name}?`,`Welche Schritte sind ${k==='E'?'Daten, die hereinkommen':k==='V'?'das, was das Programm intern rechnet oder prüft':'Ergebnisse, die das Programm herausgibt'}?`,`EVA: Eingabe holt Daten herein, Verarbeitung rechnet und prüft, Ausgabe gibt Ergebnisse heraus. Gesucht war die ${name}.`,{plainList:true})});
const ALGOS=[
 ['Du richtest für eine neue Kollegin den Arbeitsplatz-PC ein.',['Benutzerkonto im Active Directory anlegen','PC einschalten und mit dem neuen Konto anmelden','Benötigte Software installieren','Kollegin das Erstpasswort persönlich übergeben','Kollegin ändert das Passwort bei der ersten Anmeldung'],'Konto zuerst, sonst kann sich niemand anmelden. Das Passwort ändert die Kollegin zuletzt, nachdem sie es bekommen hat. Logisch, aber Computer sind bei sowas gnadenlos wörtlich.'],
 ['Ein Backup soll zurückgespielt werden.',['Fehlende Datei und Datum des Verlusts erfragen','Passende Sicherung vor diesem Datum auswählen','Datei in einen Testordner wiederherstellen','Datei prüfen und öffnen','Datei an den Originalort kopieren'],'Erst klären, was fehlt, dann die richtige Sicherung wählen. Wiederhergestellt wird erst in einen Testordner, damit kein aktueller Stand überschrieben wird.'],
 ['Ein Programm soll den Durchschnitt von drei Messwerten anzeigen.',['Drei Messwerte einlesen','Die Werte addieren','Die Summe durch 3 teilen','Das Ergebnis ausgeben'],'EVA in Reinform: Eingabe, dann zwei Verarbeitungsschritte in der richtigen Reihenfolge, dann Ausgabe. Wer zuerst teilt, bekommt Unsinn.'],
 ['Kaffee für das Team, der Klassiker unter den Algorithmen.',['Wassertank füllen','Kaffeepulver in den Filter geben','Maschine einschalten','Warten, bis der Kaffee durchgelaufen ist','Kaffee in die Tassen gießen'],'Die Reihenfolge ist Teil der Lösung. Wer die Maschine vor dem Wassertank einschaltet, bekommt heißes Nichts.'],
];
S('welt','w_algo','order',()=>{const [t,lines,y]=pick(ALGOS);return orderText(t,lines,'In welcher Reihenfolge muss der Algorithmus ablaufen?','Was muss zuerst passieren, was zuletzt?',y)});
