/* Auswahl ohne Wiederholung: Je Ablauf (Lernpfad, Training) kommt ein Typ erst nach bis zu vier anderen wieder,
   und dieselbe Aufgabenform folgt nie direkt auf sich selbst, solange die Stufe eine andere bietet. */
const PICK_HIST=new WeakMap();
function genTask(cat,lv=2,recent,subId){
 if(SUBS.some(s=>s.id===cat)){subId=cat;cat=null;}
 if(cat==='mix'||cat==='all')cat=pick(CATS)[0];
 let pool=SUBS.filter(s=>subId?s.id===subId:s.cat===cat);
 if(!pool.length)throw new Error('Unknown C# task: '+(subId||cat));
 const h=recent&&typeof recent==='object'?(PICK_HIST.get(recent)||(PICK_HIST.set(recent,{subs:[],forms:[]}),PICK_HIST.get(recent))):null;
 if(h&&!subId&&pool.length>1){
  const keep=Math.min(pool.length-1,4);let c=pool.filter(s=>!h.subs.slice(-keep).includes(s.id));
  const lf=h.forms[h.forms.length-1];const c2=c.filter(s=>s.form!==lf);if(c2.length)c=c2;
  if(c.length)pool=c;
 }
 let t,s;
 for(let i=0;i<20;i++){s=pick(pool);t=s.f(lv);if(!recent||!recent.includes(t.key))break;}
 if(h&&!subId){h.subs.push(s.id);h.forms.push(s.form);if(h.subs.length>12){h.subs.shift();h.forms.shift()}}
 return {...t,cat:s.cat,sub:s.id,subLabel:s.label,form:s.form};
}
